import React, { useState, useEffect } from "react";
import { BrowserRouter, Routes, Route } from "react-router-dom";

import NavBar from "./components/NavBar.jsx";
import Home from "./pages/Home.jsx";
import About from "./pages/About.jsx";

function App() {
  // TODO: this is where your chai entries will live
  const [entries, setEntries] = useState([]); // ← leave empty for now

  // TODO (optional later): load from localStorage on mount
  useEffect(() => {
    // const saved = localStorage.getItem("chai-entries");
    // if (saved) setEntries(JSON.parse(saved));
  }, []);

  // TODO (optional later): save to localStorage whenever entries change
  useEffect(() => {
    // localStorage.setItem("chai-entries", JSON.stringify(entries));
  }, [entries]);

  // TODO (later): write small helpers and pass them down
  // function addEntry(newEntry) { setEntries(prev => [newEntry, ...prev]); }
  // function deleteEntry(id) { setEntries(prev => prev.filter(e => e.id !== id)); }

  return (
    <BrowserRouter>
      <NavBar />
      <Routes>
        {/* HOME gets access to entries + the functions later */}
        <Route
          path="/"
          element={
            <Home
              entries={entries}
              // onAdd={addEntry}
              // onDelete={deleteEntry}
            />
          }
        />
        <Route path="/about" element={<About />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
